# --- 2. PERSISTENT STORAGE FUNCTIONS ---
COMMENTS_FILE = os.path.join(os.getcwd(), "comments.json")
QUESTIONS_FILE = os.path.join(os.getcwd(), "community_qs.json")

def load_questions():
    initial_qs = [
        {"id": 1, "u": "Ahmed", "q": "How do I distinguish between Paging and Segmentation?", "r": [{"u": "Sarah", "m": "Paging is a fixed division, while Segmentation is logical.", "t": "10:05 AM"}], "t": "10:00 AM", "likes": 5},
        {"id": 2, "u": "Sarah", "q": "Does a DFA accept Epsilon?", "r": [], "t": "11:30 AM", "likes": 3}
    ]
    if os.path.exists(QUESTIONS_FILE):
        try:
            with open(QUESTIONS_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except: return initial_qs
    return initial_qs

def save_qs(qs):
    try:
        with open(QUESTIONS_FILE, "w", encoding="utf-8") as f:
            json.dump(qs, f, ensure_ascii=False, indent=4)
    except Exception as e:
        st.error(f"Error saving: {e}")

def post_question(name, question, attachment=None):
    qs = load_questions()
    new_id = len(qs) + 1
    att_name = attachment.name if attachment else None
    qs.append({
        "id": new_id, 
        "u": name, 
        "q": question, 
        "r": [], 
        "t": time.strftime("%I:%M %p"),
        "img_name": att_name,
        "likes": 0
    })
    save_qs(qs)

def add_reply(q_id, name, reply):
    qs = load_questions()
    for q in qs:
        if q['id'] == q_id:
            q['r'].append({"u": name, "m": reply, "t": time.strftime("%I:%M %p")})
            break
    save_qs(qs)

def add_like(q_id):
    qs = load_questions()
    for q in qs:
        if q['id'] == q_id:
            q['likes'] += 1
            break
    save_qs(qs)

def load_comments():
    initial_data = [
        {"u": "Academic Support", "m": "Welcome to Mohrah's Lab! Your feedback is valued.", "t": "09:00 AM"},
        {"u": "Mohrah Almahyawi", "m": "Welcome to my educational platform, I hope you find benefit and enjoyment in learning computer science.", "t": "10:30 AM"},
        {"u": "Shoaa", "m": "The project is very wonderful and useful, thank you Mohrah for this distinguished effort.", "t": "11:15 AM"}
    ]
    if os.path.exists(COMMENTS_FILE):
        try:
            with open(COMMENTS_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except: return initial_data
    return initial_data

def detect_subject_from_comment(msg):
    """Smart routing: detect if comment is about OS or TOC"""
    msg_lower = msg.lower()
    
    os_keywords = ['operating system', 'Operating Systems', 'os', 'process', 'thread', 'scheduling', 'memory', 'deadlock', 'synchronization', 'file system', 'mass storage', 'cpu', 'Scheduling', 'Process', 'Thread', 'Memory', 'Synchronization', 'File']
    toc_keywords = ['theory of computation', 'Theory of Computation', 'toc', 'dfa', 'nfa', 'automata', 'regular', 'context free', 'turing', 'language', 'grammar', 'Automata', 'Language', 'Grammar']
    
    os_score = sum(1 for keyword in os_keywords if keyword in msg_lower)
    toc_score = sum(1 for keyword in toc_keywords if keyword in msg_lower)
    
    if os_score > toc_score and os_score > 0:
        return "Operating Systems"
    elif toc_score > os_score and toc_score > 0:
        return "Theory of Computation"
    return None

def rate_comment(msg):
    """Rate comment quality (1-5 stars)"""
    length = len(msg.split())
    has_question = '?' in msg
    has_code = '`' in msg or 'code' in msg.lower()
    has_reference = 'chapter' in msg.lower() or 'page' in msg.lower()
    
    rating = 1
    if length > 10: rating += 1
    if has_question: rating += 1
    if has_code or has_reference: rating += 1
    if length > 50: rating += 1
    
    return min(rating, 5)

def save_comment(name, msg):
    try:
        if os.path.exists(COMMENTS_FILE):
            with open(COMMENTS_FILE, "r", encoding="utf-8") as f:
                comments = json.load(f)
        else:
            comments = []
        
        rating = rate_comment(msg)
        detected_subject = detect_subject_from_comment(msg)
        
        new_comment = {
            "u": name, 
            "m": msg, 
            "t": time.strftime("%I:%M %p"),
            "rating": rating,
            "subject": detected_subject
        }
        
        comments.append(new_comment)
        
        with open(COMMENTS_FILE, "w", encoding="utf-8") as f:
            json.dump(comments, f, ensure_ascii=False, indent=4)
        
        st.session_state.comment_refresh = time.time()
        return True, detected_subject
    except Exception as e:
        st.error(f"Error saving comment: {e}")
        return False, None

